-- 20260924_exercise_form_cues.sql
-- Replace every exercise description with setup/form cues (fitness_exercise is a direct-UPDATE table).
-- Safe to re-run.

START TRANSACTION;

UPDATE fitness_exercise SET description = 'Set chest pad so you can curl forward. Exhale and round your spine, pulling ribs toward hips; don''t pull with your arms or hinge at the hips. Pause, return slowly.' WHERE exerciseID = '56d4a6b5-4720-11f1-85eb-22007a56be87';
UPDATE fitness_exercise SET description = 'Stand or lie with back flat. Arms at 90° like goalposts. Sweep arms overhead and back down, keeping wrists and elbows as close to the wall/floor as you can. Slow; mobility, not strength.' WHERE exerciseID = '27940188-601c-415f-b508-63b5120fdb8c';
UPDATE fitness_exercise SET description = 'Set knee pad so you can get 8–12 reps. Lean torso forward (lower chest). Lower until upper arms are parallel to the floor, no deeper; stop if the right shoulder pinches. Press up without snapping the elbows.' WHERE exerciseID = '18b0ef08-6757-4f3e-94d1-ae56ace397d1';
UPDATE fitness_exercise SET description = 'Pad just below hip bones, feet anchored. Hinge down with a neutral spine, then squeeze glutes to rise until body is in a straight line. Don''t arch past straight.' WHERE exerciseID = '56d49e93-4720-11f1-85eb-22007a56be87';
UPDATE fitness_exercise SET description = 'Armpits snug on the pad, elbows lined up with the pivot. Curl up and squeeze, lower slowly to almost straight. Keep wrists neutral; no shoulders lifting or rocking.' WHERE exerciseID = '56d4a34f-4720-11f1-85eb-22007a56be87';
UPDATE fitness_exercise SET description = 'Lie on back, hands lightly at ears, lower back pressed down. Rotate shoulder toward the opposite knee while extending the other leg. Move slowly; rotate the ribs, don''t yank the neck.' WHERE exerciseID = '14cdcbe9-57ad-11f1-b045-22007a56be87';
UPDATE fitness_exercise SET description = 'Rear foot laces-down on a bench, front foot far enough forward that the knee stays over the foot. Lean torso slightly forward (more glutes). Lower until back knee nearly touches, drive up through the front heel.' WHERE exerciseID = 'f0c538a6-cf91-4c16-856b-3c0f50a15f19';
UPDATE fitness_exercise SET description = 'Handles at shoulder height, step forward, slight bend in elbows (keep it fixed). Hug arms together in an arc until hands meet at chest, squeeze, then let the chest stretch on the way back.' WHERE exerciseID = '56d48e8d-4720-11f1-85eb-22007a56be87';
UPDATE fitness_exercise SET description = 'Kneel facing a high pulley, rope beside your head. Keep hips still; exhale and curl ribs toward hips, rounding the spine. Hold 1 s, return slowly. The abs move the weight, not your arms or hips.' WHERE exerciseID = 'c6fbc217-3855-48b4-9094-fa470188d9a2';
UPDATE fitness_exercise SET description = 'Cable at lowest setting, handle in the far hand, stand sideways. Raise arm out and slightly forward to shoulder height, leading with the elbow; slight elbow bend. Lower slowly. Don''t shrug.' WHERE exerciseID = '32625848-6063-4208-93b4-517d0773d5be';
UPDATE fitness_exercise SET description = 'Rope at high pulley, elbows pinned to your sides, slight forward lean. Push down and spread the rope at the bottom; stop just short of hard lockout (elbow). Return until forearms are just above parallel.' WHERE exerciseID = '56d4a4b9-4720-11f1-85eb-22007a56be87';
UPDATE fitness_exercise SET description = 'Cable high, stand sideways, arms long. Rotate through hips and torso to pull the handle diagonally down across your body, pivoting the back foot. Control the return; arms stay mostly straight.' WHERE exerciseID = '56d4a771-4720-11f1-85eb-22007a56be87';
UPDATE fitness_exercise SET description = 'Thighs locked under pad, slight lean back, chest up. Pull elbows down to your sides until the handle reaches upper chest. Squeeze lats, then let arms fully extend at the top. Don''t swing.' WHERE exerciseID = '484f9d2e-2744-48eb-ba15-7de6b1d17427';
UPDATE fitness_exercise SET description = 'Seat so handles line up with mid-chest. Shoulder blades pinched back and down, feet flat. Press without locking out hard; lower slowly until you feel a chest stretch. Neutral grip if available.' WHERE exerciseID = '56d48c60-4720-11f1-85eb-22007a56be87';
UPDATE fitness_exercise SET description = 'Lie flat, shoulder blades squeezed together, feet planted. Lower dumbbells to chest level with elbows ~45° from your body, then press up and slightly in. Control the bottom; don''t bounce.' WHERE exerciseID = '56d4a8c5-4720-11f1-85eb-22007a56be87';
UPDATE fitness_exercise SET description = 'Hinge forward ~45° with a flat back, knees soft (or one hand on bench). Pull the dumbbell toward your hip, elbow close to your side. Squeeze your back, lower until the arm is straight.' WHERE exerciseID = '56d4b243-4720-11f1-85eb-22007a56be87';
UPDATE fitness_exercise SET description = 'Stand tall, elbows at your sides. Curl up, turning palms up, and squeeze; lower slowly all the way. No swinging or elbows drifting forward.' WHERE exerciseID = '56d4a97a-4720-11f1-85eb-22007a56be87';
UPDATE fitness_exercise SET description = 'Lie flat, dumbbells above chest, palms facing, elbows slightly bent and fixed. Open arms in a wide arc until you feel a chest stretch (elbows about bench level), then hug them back up.' WHERE exerciseID = '56d4b441-4720-11f1-85eb-22007a56be87';
UPDATE fitness_exercise SET description = 'Stand tall, slight elbow bend. Raise dumbbells in front to shoulder height, thumbs slightly up. Lower slowly. No leaning back or swinging.' WHERE exerciseID = '56d4b660-4720-11f1-85eb-22007a56be87';
UPDATE fitness_exercise SET description = 'Hold one dumbbell vertically against your chest. Feet shoulder-width, toes slightly out. Sit down between your heels, chest up, knees tracking over toes. Drive up through the whole foot.' WHERE exerciseID = '56d4b389-4720-11f1-85eb-22007a56be87';
UPDATE fitness_exercise SET description = 'Palms facing each other, elbows at your sides. Curl up without rotating the wrist, squeeze, lower slowly. Keep the wrist straight.' WHERE exerciseID = '56d4b73f-4720-11f1-85eb-22007a56be87';
UPDATE fitness_exercise SET description = 'Upper back on bench edge (shoulder-blade level), feet flat, shins vertical at the top. Dumbbell on hips (use a pad). Tuck chin, drive through heels, squeeze glutes to full hip extension. Don''t arch the low back.' WHERE exerciseID = '4e50f7cd-4f6e-4d0b-83cf-543ab969bda2';
UPDATE fitness_exercise SET description = 'Slight lean forward, arms slightly in front of your body. Raise out to shoulder height leading with the elbows, pinky side slightly up. Lower slowly. Don''t shrug or swing.' WHERE exerciseID = '56d4b1f2-4720-11f1-85eb-22007a56be87';
UPDATE fitness_exercise SET description = 'Step forward, lower until both knees are ~90°, front knee over the foot, torso upright. Push through the front heel to return. Keep hips level.' WHERE exerciseID = '56d4b3eb-4720-11f1-85eb-22007a56be87';
UPDATE fitness_exercise SET description = 'Overhand grip, elbows at sides. Curl slowly and lower slowly. Go light: this loads the same tendons as tennis elbow.' WHERE exerciseID = '14d0bd2c-57ad-11f1-b045-22007a56be87';
UPDATE fitness_exercise SET description = 'Seated, back supported, palms facing in (neutral grip is easier on the shoulder). Press overhead in a slight arc, stop just short of lockout, lower to ear level. Keep ribs down.' WHERE exerciseID = '56d4a926-4720-11f1-85eb-22007a56be87';
UPDATE fitness_exercise SET description = 'Stand tall, arms straight, dumbbells at your sides; use straps. Lift shoulders straight up toward the ears, hold 1–2 s, lower fully. No rolling the shoulders.' WHERE exerciseID = '56d4b6e7-4720-11f1-85eb-22007a56be87';
UPDATE fitness_exercise SET description = 'One dumbbell held overhead with both hands, elbows pointing forward. Lower behind your head for a deep stretch, then extend. Keep elbows narrow; go light if the elbow complains.' WHERE exerciseID = '56d4b190-4720-11f1-85eb-22007a56be87';
UPDATE fitness_exercise SET description = 'Forearms on thighs or a bench, palms up, wrists past the edge. Curl the wrist up, lower slowly. Light weight, full range.' WHERE exerciseID = '14d0e5fe-57ad-11f1-b045-22007a56be87';
UPDATE fitness_exercise SET description = 'Stand tall, slight elbow bend. Raise dumbbells in front to shoulder height, thumbs slightly up. Lower slowly. No leaning back or swinging.' WHERE exerciseID = '9c868f11-207a-4c56-b091-b56551bd4425';
UPDATE fitness_exercise SET description = 'Hinge forward to nearly flat back (or chest on incline bench). Slight elbow bend; raise arms out wide to shoulder height, squeezing the rear shoulders. Lower slowly. Don''t squeeze shoulder blades hard.' WHERE exerciseID = '6b354a0e-c803-432a-8512-5b73d18a25eb';
UPDATE fitness_exercise SET description = 'Rope at upper-chest/face height. Pull toward your forehead, spreading the rope and rotating so knuckles point back, elbows high. Pause, return slowly. Good for the tight right shoulder.' WHERE exerciseID = 'c0d3e7f7-440c-4dfe-b84a-379e319eaea5';
UPDATE fitness_exercise SET description = 'Back flat on pad, feet shoulder-width mid-platform. Lower until thighs are at least parallel, knees tracking over toes. Drive up without locking knees hard.' WHERE exerciseID = '56d48c07-4720-11f1-85eb-22007a56be87';
UPDATE fitness_exercise SET description = 'Grip the bar shoulder-width, relax into a dead hang, shoulders slightly engaged (not shrugged to ears). Breathe. Good for shoulder mobility; ease off if the elbow is sore.' WHERE exerciseID = 'd4707317-4ecb-41c0-8cb9-c7344887d2f3';
UPDATE fitness_exercise SET description = 'Sit tall, back against the pad. Push knees out against the pads, pause, return slowly without letting the weight stack touch. Leaning slightly forward targets the glutes more.' WHERE exerciseID = '56d482d9-4720-11f1-85eb-22007a56be87';
UPDATE fitness_exercise SET description = 'Sit tall, pads on the inside of the knees. Squeeze the legs together, pause, return slowly to a comfortable stretch. Don''t bounce at the open position.' WHERE exerciseID = '56d48ba5-4720-11f1-85eb-22007a56be87';
UPDATE fitness_exercise SET description = 'Seat so handles line up with upper chest. Shoulder blades back and down. Press up and slightly in, lower slowly to a chest stretch. Don''t lock out hard.' WHERE exerciseID = '56d48e23-4720-11f1-85eb-22007a56be87';
UPDATE fitness_exercise SET description = 'Bench at ~30°. Shoulder blades squeezed together, feet planted. Lower dumbbells to upper chest, elbows ~45° from body, palms slightly turned in. Press up and together. Control the stretch.' WHERE exerciseID = 'dffec448-3523-456c-934e-81300f61071a';
UPDATE fitness_exercise SET description = 'Thighs locked under pad, neutral grip if possible, slight lean back, chest up. Drive elbows down to your sides, handle to upper chest. Squeeze, then let arms straighten fully at the top. No swinging.' WHERE exerciseID = '56d48ee4-4720-11f1-85eb-22007a56be87';
UPDATE fitness_exercise SET description = 'Seat so shoulders line up with the machine pivot. Lead with the elbows, raise to shoulder height, pause, lower slowly. Don''t shrug.' WHERE exerciseID = '56d49f9e-4720-11f1-85eb-22007a56be87';
UPDATE fitness_exercise SET description = 'Knees aligned with the pivot, pad just above the heels. Curl heels toward glutes, squeeze, lower slowly to almost straight. Keep hips down on the pad.' WHERE exerciseID = '56d4812d-4720-11f1-85eb-22007a56be87';
UPDATE fitness_exercise SET description = 'Knee aligned with the pivot, pad on the lower shin. Extend fully and squeeze quads for 1 s, lower slowly. Don''t kick or let the stack slam.' WHERE exerciseID = '56d4562d-4720-11f1-85eb-22007a56be87';
UPDATE fitness_exercise SET description = 'Back and hips flat on pad, feet shoulder-width mid-platform. Lower until knees are near 90° without the low back rounding off the pad. Press through the whole foot; don''t lock knees. Feet higher = more glutes.' WHERE exerciseID = '56d453a2-4720-11f1-85eb-22007a56be87';
UPDATE fitness_exercise SET description = 'Captain''s chair: back against pad, forearms on rests. Raise knees (or straight legs) to hip height or higher, curling the pelvis up. Lower slowly, no swinging.' WHERE exerciseID = '14d07e81-57ad-11f1-b045-22007a56be87';
UPDATE fitness_exercise SET description = 'Cables at lowest setting, step forward, slight elbow bend (keep it fixed). Sweep hands up and together to chin height, squeeze upper chest. Return slowly to a stretch. Light and controlled.' WHERE exerciseID = 'babb87d6-a256-4b7e-8635-b94dd5d45eaa';
UPDATE fitness_exercise SET description = 'Seat so handles are at chest height, shoulder blades back. Elbows slightly bent; bring handles together, squeeze 1 s, then let the chest stretch as they open. Don''t let shoulders roll forward.' WHERE exerciseID = '56d48cb5-4720-11f1-85eb-22007a56be87';
UPDATE fitness_exercise SET description = 'Hips high in an inverted V, hands slightly wider than shoulders. Lower the top of your head toward the floor in front of your hands, elbows ~45°. Press back up. Feet on a step makes it harder.' WHERE exerciseID = '14cd3af1-57ad-11f1-b045-22007a56be87';
UPDATE fitness_exercise SET description = 'Forearms under shoulders, body in a straight line from head to heels. Squeeze glutes, brace abs like bracing for a punch, breathe. Stop when hips sag.' WHERE exerciseID = '14cd9430-57ad-11f1-b045-22007a56be87';
UPDATE fitness_exercise SET description = 'Armpits snug on the pad, elbows lined up with the pivot. Curl and squeeze, lower slowly to nearly straight. Don''t let the weight yank the elbow straight at the bottom.' WHERE exerciseID = '56d4a466-4720-11f1-85eb-22007a56be87';
UPDATE fitness_exercise SET description = 'Hands just outside shoulders, body straight, glutes tight. Lower chest to just above the floor, elbows ~45° from body, then press up. Knees down or hands on bench to make it easier.' WHERE exerciseID = '14ccd796-57ad-11f1-b045-22007a56be87';
UPDATE fitness_exercise SET description = 'Chest against pad, handles at shoulder height, arms nearly straight. Sweep arms back in a wide arc, leading with the elbows, until in line with your body. Pause, return slowly.' WHERE exerciseID = '56d49ff6-4720-11f1-85eb-22007a56be87';
UPDATE fitness_exercise SET description = 'Sit, lean back ~45°, feet down (or up for harder), spine long. Rotate the ribs side to side, hands following. Slow and controlled; don''t just swing the arms.' WHERE exerciseID = '14cfe70e-57ad-11f1-b045-22007a56be87';
UPDATE fitness_exercise SET description = 'Feet on platform, knees soft, sit tall. Neutral handle. Pull to lower ribs, elbows close to sides, squeezing shoulder blades together. Let arms and shoulders reach forward on the return without rounding.' WHERE exerciseID = '56d48f3b-4720-11f1-85eb-22007a56be87';
UPDATE fitness_exercise SET description = 'Pad snug on lower thighs, balls of feet on the edge. Lower heels for a deep stretch (pause), push up as high as possible, squeeze 1 s. Slow; no bouncing.' WHERE exerciseID = '56d4820b-4720-11f1-85eb-22007a56be87';
UPDATE fitness_exercise SET description = 'Cable at elbow height, stand sideways. Elbow bent 90° and pinned to your side (towel under the arm helps). Rotate the forearm out, away from your body, pause, return slowly. Very light.' WHERE exerciseID = '1d96e89e-501d-458e-a6e7-09b8555952d6';
UPDATE fitness_exercise SET description = 'Seat so handles start at shoulder height; neutral grip if available. Back against pad, ribs down. Press up without hard lockout, lower slowly to shoulder level. Stop short of any right-shoulder pinch.' WHERE exerciseID = '56d49f48-4720-11f1-85eb-22007a56be87';
UPDATE fitness_exercise SET description = 'Stand loose, arms relaxed. Rotate the torso side to side and let arms swing and wrap around the body. Easy pace; warm-up and mobility only.' WHERE exerciseID = '08987f54-7527-46db-b282-5740d4dab971';
UPDATE fitness_exercise SET description = 'High pulley, one handle, kneel or sit facing it. Start with arm stretched overhead. Pull the elbow down to your hip (think elbow to back pocket). Squeeze the lat, return to a full stretch.' WHERE exerciseID = 'b021195b-d36c-4154-bab7-f7be2d7568b9';
UPDATE fitness_exercise SET description = 'Follow the video. Stand tall, brace your abs throughout, and move with control rather than speed.' WHERE exerciseID = '351ece07-c5a0-43a9-b40e-9128e379a9d6';
UPDATE fitness_exercise SET description = 'Shoulders under pads, balls of feet on the edge, knees straight but not locked. Lower heels for a deep stretch (pause), rise as high as possible, squeeze 1 s. No bouncing.' WHERE exerciseID = '56d4827c-4720-11f1-85eb-22007a56be87';
UPDATE fitness_exercise SET description = 'Kneel on pad, grip shoulder-width (neutral handles if available). Pull chest toward the bar, driving elbows down to your sides. Lower all the way to straight arms. Less assist = harder.' WHERE exerciseID = '7b07a014-5ed6-4ee1-91b4-585f7f047519';
UPDATE fitness_exercise SET description = 'Chest on pad (if present), flat back. Pull the handles toward lower chest, elbows at ~45°, squeeze shoulder blades. Lower until arms are straight.' WHERE exerciseID = '56d49e04-4720-11f1-85eb-22007a56be87';
UPDATE fitness_exercise SET description = 'Sit tall, knees locked in. Rotate the torso against the resistance using your obliques, pause, return slowly. Keep the range comfortable; don''t whip it.' WHERE exerciseID = '56d4a71e-4720-11f1-85eb-22007a56be87';
UPDATE fitness_exercise SET description = 'Stand tall, don''t hold the rails. Brisk walk (≈3.5 mph); add incline for more effort. Short, quick steps, arms swinging naturally.' WHERE exerciseID = '738dbbc3-5771-11f1-b045-22007a56be87';
UPDATE fitness_exercise SET description = 'Sit tall, back against pad. Push handles down until arms are nearly straight, then return slowly until elbows are ~90°. Keep shoulders down; stop before any shoulder pinch.' WHERE exerciseID = '56d4a413-4720-11f1-85eb-22007a56be87';
UPDATE fitness_exercise SET description = 'Elbows lined up with the pivot, upper arms flat on the pad. Extend to nearly straight (no hard lockout), squeeze, return slowly. Keep wrists neutral.' WHERE exerciseID = '56d4a3bd-4720-11f1-85eb-22007a56be87';

COMMIT;
